import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/use-drag-select-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  parameters: {
    layout: "centered",
    docs: { description: { component: "## Usage\n\nSelects or clears neighboring items with a pointer drag. The example uses joined selection items with checkbox and keyboard support.\n\nImport `useDragSelect` from `@/registry/erbium/hooks/use-drag-select`. Supply `resolve` and `selectRange` callbacks and spread its handlers on the containing element." } },
  },
} satisfies Meta;

export default { ...meta, title: "Hooks/Use Drag Select",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/use-drag-select-demo";

const Example = () => <Demo />;

export default Example;
